CREATE TYPE public.app_role AS ENUM ('student','landlord','admin');
CREATE TYPE public.room_type AS ENUM ('single','sharing','studio','bachelor');
CREATE TABLE public.profiles (id uuid PRIMARY KEY, full_name text, phone text, avatar_url text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Profile owner read" ON public.profiles FOR SELECT TO authenticated USING (id = (SELECT auth.uid()));
CREATE POLICY "Profile owner insert" ON public.profiles FOR INSERT TO authenticated WITH CHECK (id = (SELECT auth.uid()));
CREATE POLICY "Profile owner edit" ON public.profiles FOR UPDATE TO authenticated USING (id = (SELECT auth.uid())) WITH CHECK (id = (SELECT auth.uid()));
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own roles" ON public.user_roles FOR SELECT TO authenticated USING (user_id = (SELECT auth.uid()));
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE TABLE public.landlords (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE, business_name text NOT NULL, contact_email text, phone text, whatsapp text, verification text NOT NULL DEFAULT 'unverified' CHECK (verification IN ('unverified','pending','verified','rejected')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.landlords TO authenticated; GRANT ALL ON public.landlords TO service_role;
ALTER TABLE public.landlords ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Landlord own read" ON public.landlords FOR SELECT TO authenticated USING (user_id = (SELECT auth.uid()));
CREATE POLICY "Landlord own edit" ON public.landlords FOR UPDATE TO authenticated USING (user_id = (SELECT auth.uid())) WITH CHECK (user_id = (SELECT auth.uid()));
CREATE FUNCTION public.become_landlord(_business_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE _id uuid; BEGIN IF auth.uid() IS NULL OR length(trim(_business_name)) < 2 THEN RAISE EXCEPTION 'Invalid landlord request'; END IF; INSERT INTO public.landlords(user_id,business_name) VALUES(auth.uid(),trim(_business_name)) ON CONFLICT(user_id) DO NOTHING; SELECT id INTO _id FROM public.landlords WHERE user_id = auth.uid(); INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),'landlord') ON CONFLICT DO NOTHING; RETURN _id; END $$;
GRANT EXECUTE ON FUNCTION public.become_landlord(text) TO authenticated;
CREATE TABLE public.institutions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, province text, sort_order integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.institutions TO anon, authenticated; GRANT ALL ON public.institutions TO service_role;
ALTER TABLE public.institutions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public institutions" ON public.institutions FOR SELECT TO anon, authenticated USING (true);
CREATE TABLE public.amenities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, label text NOT NULL, icon text);
GRANT SELECT ON public.amenities TO anon, authenticated; GRANT ALL ON public.amenities TO service_role;
ALTER TABLE public.amenities ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public amenities" ON public.amenities FOR SELECT TO anon, authenticated USING (true);
ALTER TABLE public.listings ADD COLUMN room_type public.room_type, ADD COLUMN available_from date, ADD COLUMN distance_km numeric(4,1), ADD COLUMN nsfas_accredited boolean NOT NULL DEFAULT false, ADD COLUMN deposit_zar integer, ADD COLUMN city text, ADD COLUMN landlord_id uuid REFERENCES public.landlords(id), ADD COLUMN published_at timestamptz;
CREATE INDEX listings_extended_filter_idx ON public.listings(status,province,room_type,monthly_rent);
CREATE TABLE public.listing_images (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), listing_id uuid NOT NULL REFERENCES public.listings(id) ON DELETE CASCADE, storage_path text NOT NULL, alt_text text NOT NULL DEFAULT '', sort_order integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.listing_images TO anon; GRANT SELECT, INSERT, UPDATE, DELETE ON public.listing_images TO authenticated; GRANT ALL ON public.listing_images TO service_role;
ALTER TABLE public.listing_images ENABLE ROW LEVEL SECURITY;
CREATE POLICY "View approved images or own" ON public.listing_images FOR SELECT TO anon, authenticated USING (EXISTS (SELECT 1 FROM public.listings l WHERE l.id=listing_id AND (l.status='approved' OR l.owner_id=(SELECT auth.uid()))));
CREATE POLICY "Manage own images" ON public.listing_images FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.listings l WHERE l.id=listing_id AND l.owner_id=(SELECT auth.uid()))) WITH CHECK (EXISTS (SELECT 1 FROM public.listings l WHERE l.id=listing_id AND l.owner_id=(SELECT auth.uid())));
CREATE TABLE public.listing_amenities (listing_id uuid NOT NULL REFERENCES public.listings(id) ON DELETE CASCADE, amenity_id uuid NOT NULL REFERENCES public.amenities(id) ON DELETE CASCADE, PRIMARY KEY(listing_id,amenity_id));
GRANT SELECT ON public.listing_amenities TO anon; GRANT SELECT, INSERT, DELETE ON public.listing_amenities TO authenticated; GRANT ALL ON public.listing_amenities TO service_role;
ALTER TABLE public.listing_amenities ENABLE ROW LEVEL SECURITY;
CREATE POLICY "View approved amenities or own" ON public.listing_amenities FOR SELECT TO anon, authenticated USING (EXISTS (SELECT 1 FROM public.listings l WHERE l.id=listing_id AND (l.status='approved' OR l.owner_id=(SELECT auth.uid()))));
CREATE POLICY "Manage own amenities" ON public.listing_amenities FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.listings l WHERE l.id=listing_id AND l.owner_id=(SELECT auth.uid()))) WITH CHECK (EXISTS (SELECT 1 FROM public.listings l WHERE l.id=listing_id AND l.owner_id=(SELECT auth.uid())));
CREATE TABLE public.enquiries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), listing_id uuid NOT NULL REFERENCES public.listings(id) ON DELETE CASCADE, student_id uuid NOT NULL, message text NOT NULL CHECK(length(message) BETWEEN 10 AND 2000), preferred_move_in date, status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','contacted','viewing_booked','closed')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.enquiries TO authenticated; GRANT ALL ON public.enquiries TO service_role;
ALTER TABLE public.enquiries ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own enquiries" ON public.enquiries FOR SELECT TO authenticated USING (student_id=(SELECT auth.uid()) OR EXISTS (SELECT 1 FROM public.listings l WHERE l.id=listing_id AND l.owner_id=(SELECT auth.uid())));
CREATE POLICY "Enquire about approved listings" ON public.enquiries FOR INSERT TO authenticated WITH CHECK (student_id=(SELECT auth.uid()) AND EXISTS (SELECT 1 FROM public.listings l WHERE l.id=listing_id AND l.status='approved'));
CREATE TABLE public.saved_listings (user_id uuid NOT NULL, listing_id uuid NOT NULL REFERENCES public.listings(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,listing_id));
GRANT SELECT, INSERT, DELETE ON public.saved_listings TO authenticated; GRANT ALL ON public.saved_listings TO service_role;
ALTER TABLE public.saved_listings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Manage own saved" ON public.saved_listings FOR ALL TO authenticated USING (user_id=(SELECT auth.uid())) WITH CHECK (user_id=(SELECT auth.uid()));
CREATE TABLE public.notify_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL CHECK(email ~* '^[^@ ]+@[^@ ]+[.][^@ ]+$'), province text, max_rent_zar integer, consent_popia boolean NOT NULL DEFAULT false CHECK(consent_popia), created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.notify_requests TO anon, authenticated; GRANT ALL ON public.notify_requests TO service_role;
ALTER TABLE public.notify_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Consent to notifications" ON public.notify_requests FOR INSERT TO anon, authenticated WITH CHECK(consent_popia=true);
CREATE TABLE public.verification_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), landlord_id uuid NOT NULL REFERENCES public.landlords(id) ON DELETE CASCADE, doc_type text NOT NULL, storage_path text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.verification_documents TO authenticated; GRANT ALL ON public.verification_documents TO service_role;
ALTER TABLE public.verification_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Landlord own documents" ON public.verification_documents FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.landlords ld WHERE ld.id=landlord_id AND ld.user_id=(SELECT auth.uid())));
CREATE POLICY "Landlord add documents" ON public.verification_documents FOR INSERT TO authenticated WITH CHECK(EXISTS(SELECT 1 FROM public.landlords ld WHERE ld.id=landlord_id AND ld.user_id=(SELECT auth.uid())));
CREATE FUNCTION public.search_listings(_province text DEFAULT NULL,_institution text DEFAULT NULL,_max_rent numeric DEFAULT NULL,_room_type public.room_type DEFAULT NULL,_move_in date DEFAULT NULL,_max_distance numeric DEFAULT NULL,_nsfas boolean DEFAULT NULL,_lgbtq boolean DEFAULT NULL,_pet boolean DEFAULT NULL,_accessible boolean DEFAULT NULL,_sort text DEFAULT 'newest',_limit integer DEFAULT 24,_offset integer DEFAULT 0) RETURNS SETOF public.listings LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT l.* FROM public.listings l WHERE l.status='approved' AND (_province IS NULL OR l.province=_province) AND (_institution IS NULL OR l.institution=_institution) AND (_max_rent IS NULL OR l.monthly_rent<=_max_rent) AND (_room_type IS NULL OR l.room_type=_room_type) AND (_move_in IS NULL OR l.available_from IS NULL OR l.available_from<=_move_in) AND (_max_distance IS NULL OR l.distance_km<=_max_distance) AND (NOT coalesce(_nsfas,false) OR l.nsfas_accredited) AND (NOT coalesce(_lgbtq,false) OR l.lgbtq_friendly) AND (NOT coalesce(_pet,false) OR l.pet_friendly) AND (NOT coalesce(_accessible,false) OR l.accessible) ORDER BY CASE WHEN _sort='price_asc' THEN l.monthly_rent END ASC, CASE WHEN _sort='price_desc' THEN l.monthly_rent END DESC, CASE WHEN _sort='distance' THEN l.distance_km END ASC, l.created_at DESC LIMIT least(greatest(_limit,1),60) OFFSET greatest(_offset,0) $$;
GRANT EXECUTE ON FUNCTION public.search_listings(text,text,numeric,public.room_type,date,numeric,boolean,boolean,boolean,boolean,text,integer,integer) TO anon,authenticated;